fn push(h:[]i64,count:*usize,is_max:bool,x:i64)void{var i=count.*;h[i]=x;count.*+=1;while(i>0){const p=(i-1)/2;const bad=if(is_max)h[p]<h[i] else h[p]>h[i];if(!bad)break;std.mem.swap(i64,&h[p],&h[i]);i=p;}}
fn pop(h:[]i64,count:*usize,is_max:bool)i64{const x=h[0];count.*-=1;h[0]=h[count.*];var i:usize=0;while(true){const l=2*i+1;const r=l+1;var b=i;if(l<count.* and (if(is_max)h[l]>h[b] else h[l]<h[b]))b=l;if(r<count.* and (if(is_max)h[r]>h[b] else h[r]<h[b]))b=r;if(b==i)break;std.mem.swap(i64,&h[i],&h[b]);i=b;}return x;}
fn store(x:i64,out:[]u8,p:usize)void{const u:u64=@bitCast(x);for(0..8)|b|out[p+b]=@truncate(u>>@intCast(8*b));}
const std=@import("std");
export fn median_of_running_array_integer(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<2)return -1;const v=input.?[0..length];if(v[0]<1 or v[0]>256 or length!=@as(usize,@intCast(v[0]))+1)return -1;const n:usize=@intCast(v[0]);for(v[1..])|x|{if(x< -1_000_000 or x>1_000_000)return -1;}if(output==null or capacity<n*8)return -2;var lo:[256]i64=undefined;var hi:[256]i64=undefined;var nl:usize=0;var nh:usize=0;for(0..n)|i|{const x=v[i+1];if(nh>0 and x<hi[0])push(&lo,&nl,true,x) else push(&hi,&nh,false,x);if(nl>nh+1)push(&hi,&nh,false,pop(&lo,&nl,true)) else if(nh>nl+1)push(&lo,&nl,true,pop(&hi,&nh,false));const m:i64=if(nl==nh)@divTrunc(lo[0]+hi[0],2) else if(nl>nh)lo[0] else hi[0];store(m,output.?[0..n*8],i*8);}return @intCast(n*8);}
